constexpr uint16_t kLabEnemyCount = sizeof(kLabEnemies) / sizeof(kLabEnemies[0]);

// one pool slot, field for field with enemies.c's Enemy
struct EnemySlot {
    uint8_t state = kEnemyOff;
    uint8_t kind = 0;
    int8_t dir = -1;
    uint8_t grounded = 1;
    uint8_t x_force = 0;
    uint8_t y_accum = 0;
    int8_t dy = 0;
    uint8_t lead_col = 0;
    uint8_t foot_col = 0;
    uint8_t grace = 0;
    uint16_t timer = 0;
    uint16_t pos_x = 0;
    int16_t pos_y = 0;

    uint8_t lead() const {
        return static_cast<uint8_t>((dir > 0 ? static_cast<uint16_t>(pos_x + kEnemyBoxPx - 1) : pos_x) >> 4);
    }

    uint8_t foot() const {
        return static_cast<uint8_t>(static_cast<uint16_t>(pos_x + kEnemyBoxPx / 2) >> 4);
    }
};

// the host twin of games/mario/src/player.c: the same fixed-point state in the same types, stepped
// in the same order. the planner searches with it, and the autopilot test replays its predictions
// against the rom frame for frame, so any drift between the two is a test failure.
struct PlayerSim {
    int8_t x_speed = 0;
    uint8_t x_accum = 0;
    uint8_t x_force = 0;
    uint16_t x_pos = static_cast<uint16_t>(kHostLevels[kLevel11].start_column * kBlockPx);
    int8_t y_speed = 0;
    uint8_t y_accum = 0;
    int16_t y_pos = static_cast<int16_t>(kHostLevels[kLevel11].start_row * kBlockPx - kPlayerBoxPx);
    int16_t jump_origin_y = y_pos;
    uint8_t on_ground = 1;
    uint8_t jump_tier = 0;
    uint8_t a_prev = 0;
    // player.c's 16x32 body. the planner never grows, but the powerup tests plan super moves with
    // the same twin, so the collision box has to follow him
    uint8_t big = 0;
    // one bit per compiled hidden block, set the moment a rising head materializes it. it rides
    // inside the sim so the planner's lookahead copies inherit exactly what the real run has done
    uint32_t hidden_solid = 0;
    // the cell this frame's head bump struck, or (-1, -1); the bump tests search on it
    int16_t bumped_column = -1;
    int16_t bumped_row = -1;
    // blocks.c's one item slot, as far as a planner needs it. the twin has to carry it because a
    // mushroom he walks into freezes the whole world for the grow, and a star changes what every
    // enemy contact after it means: plan_level treats collecting one as a dead end and routes round
    // it, so a dispenser he opens on the way past is left behind rather than avoided
    uint8_t item_kind = 0;
    uint8_t item_phase = 0;
    uint8_t item_timer = 0;
    uint16_t item_x = 0;
    int16_t item_y = 0;
    int16_t item_origin_y = 0;
    int8_t item_dir = 1;
    int8_t item_dy = 0;
    uint8_t item_accum = 0;
    uint8_t item_grounded = 0;
    // one bit per compiled block that has already paid out; a spent one never dispenses twice
    uint32_t spent = 0;
    bool collected = false;

    // the enemy pool rides inside the player sim rather than beside it: the planner searches by
    // copying whole sims, and a lookahead that forgot the goombas would plan straight into one.
    // every field and every step below mirrors games/mario/src/enemies.c
    std::array<EnemySlot, kEnemySlots> pool{};
    // the pool stays packed into [0, live), exactly as enemies.c keeps it
    uint8_t live = 0;
    // which level is loaded; every probe below answers against its compiled grid and lists
    const HostLevel* lv = &kHostLevels[kLevel11];
    const LevelEnemy* roster = kLevel11Enemies;
    uint16_t roster_count = kLevel11EnemyCount;
    uint16_t cursor = 0;
    uint16_t cam_x = 0;
    // camera.c's own scy: the band it drifts to while he moves, and where it currently sits. the
    // pan is frozen while he stands perfectly still, so a plan that ends standing has to check it
    uint8_t cam_y = kScyMax;
    uint8_t band = kScyMax;
    uint16_t points = 0;
    uint8_t stomp_chain = 0;
    uint8_t shell_chain = 0;
    // the frame's contact code and whether one of them ever ended the run
    uint8_t contact = kEnemyHitNone;
    bool damaged = false;
    // the spawner refused a slot on a full row this frame; the scanline-cap test watches it
    bool refused = false;

    // --- the hazard pools, field for field with games/mario/src/hazards.c -----------------------
    struct LiftSim {
        uint16_t x = 0;
        int16_t y = 0;
        uint16_t lo = 0;
        uint16_t hi = 0;
        int8_t dir = 1;
        int8_t dx = 0;
        int8_t dy = 0;
        uint8_t vertical = 0;
    };
    std::array<LiftSim, kLiftSlots> lifts{};
    uint8_t lift_count = 0;
    std::array<uint8_t, kBarSlots> bar_column{};
    std::array<uint8_t, kBarSlots> bar_row{};
    uint8_t bar_count = 0;
    uint8_t spin_accum = 0;
    uint8_t spin_step = 0;
    uint16_t bowser_x = 0;
    int16_t bowser_y = 0;
    uint16_t bowser_lo = 0;
    uint16_t bowser_hi = 0;
    int8_t bowser_dir = -1;
    uint8_t bowser_force = 0;
    uint8_t bowser_live = 0;
    uint16_t axe_x = 0;
    int16_t axe_y = 0;
    uint8_t axe_live = 0;
    uint8_t hazard_active = 0;
    uint8_t hazard_near = 0;
    uint16_t hazard_min_x = 0xFFFF;
    uint16_t hazard_max_x = 0;
    // the lift deck he rides, and the box top before this frame's vertical step
    uint8_t riding = 0xFF;
    int16_t prev_y = 0;
    // frames he has been standing for. a plan that presses a on the very frame the twin lands is
    // lost on a rom that landed one frame later - it finds a already held and never jumps at all -
    // so plan_level waits for the second grounded frame and the route survives a missed vsync
    uint8_t grounded_for = 0;
    // the run ended on the axe: for a castle this is what "reached the end" means
    bool axed = false;

    // flow.c's level load, as far as the twin models it. the rom's own load runs the lcd-off
    // rebuild inside one game frame and then plays on, and its lifts and firebars have been turning
    // for however many frames the test waited before it started driving: the twin idles out the
    // same count, or the deck he plans to land on is somewhere else by the time he gets there
    void load_level(int index) {
        load_host(kHostLevels[index]);
        for (int i = 0; i < kLevelSettleFrames; ++i) {
            step(0);
        }
    }

    void load_host(const HostLevel& l) {
        *this = PlayerSim{};
        lv = &l;
        roster = l.enemies;
        roster_count = static_cast<uint16_t>(l.enemy_count);
        x_pos = static_cast<uint16_t>(l.start_column * kBlockPx);
        y_pos = static_cast<int16_t>(l.start_row * kBlockPx - kPlayerBoxPx);
        jump_origin_y = y_pos;
        prev_y = y_pos;
        for (int i = 0; i < l.object_count; ++i) {
            const LevelObject& o = l.objects[i];

            if (o.kind != kObjPipe) {
                const uint16_t px = static_cast<uint16_t>(o.column * kBlockPx);
                const uint16_t far = static_cast<uint16_t>(px + ((o.param & kLiftSpanMask) * kBlockPx));

                hazard_min_x = std::min(hazard_min_x, px);
                hazard_max_x = std::max(hazard_max_x, far);
            }
            if (o.kind == kObjFirebar) {
                if (bar_count < kBarSlots) {
                    bar_column[bar_count] = static_cast<uint8_t>(o.column);
                    bar_row[bar_count] = o.row;
                    ++bar_count;
                }
            } else if (o.kind == kObjLiftH || o.kind == kObjLiftV) {
                if (lift_count >= kLiftSlots) {
                    continue;
                }
                LiftSim& f = lifts[lift_count];
                const int span = o.param & kLiftSpanMask;

                f.vertical = o.kind == kObjLiftV ? 1 : 0;
                if (f.vertical != 0) {
                    f.lo = static_cast<uint16_t>(o.row * kBlockPx);
                    f.hi = static_cast<uint16_t>((o.row + span) * kBlockPx);
                    f.x = static_cast<uint16_t>(o.column * kBlockPx);
                } else {
                    f.lo = static_cast<uint16_t>(o.column * kBlockPx);
                    f.hi = static_cast<uint16_t>((o.column + span) * kBlockPx);
                    f.y = static_cast<int16_t>(o.row * kBlockPx);
                }
                if ((o.param & kLiftReverse) != 0) {
                    f.dir = -1;
                    if (f.vertical != 0) {
                        f.y = static_cast<int16_t>(f.hi);
                    } else {
                        f.x = f.hi;
                    }
                } else {
                    f.dir = 1;
                    if (f.vertical != 0) {
                        f.y = static_cast<int16_t>(f.lo);
                    } else {
                        f.x = f.lo;
                    }
                }
                ++lift_count;
            } else if (o.kind == kObjBowser) {
                bowser_live = 1;
                bowser_x = static_cast<uint16_t>(o.column * kBlockPx);
                bowser_y = static_cast<int16_t>(o.row * kBlockPx);
                bowser_lo = bowser_x;
                bowser_hi = static_cast<uint16_t>((o.column + o.param) * kBlockPx);
                bowser_dir = -1;
            } else if (o.kind == kObjAxe) {
                axe_live = 1;
                axe_x = static_cast<uint16_t>(o.column * kBlockPx);
                axe_y = static_cast<int16_t>(o.row * kBlockPx);
            }
        }
        hazard_active = static_cast<uint8_t>(lift_count + bar_count + bowser_live + axe_live);
        hazard_near = hazard_active;
    }

    uint16_t max_x() const {
        return max_world_x(*lv);
    }

    void use_lab() {
        roster = kLabEnemies;
        roster_count = kLabEnemyCount;
    }

    // the run is over either way: the planner treats a goomba like a pit
    bool dead() const {
        return fell() || damaged;
    }

    void remove_at(uint8_t i) {
        --live;
        pool[i] = pool[live];
    }

    void award(const uint16_t* table, uint8_t count, uint8_t& chain) {
        points = static_cast<uint16_t>(points + table[chain < count ? chain : count - 1]);
        if (chain < 0xFF) {
            ++chain;
        }
    }

    void enemy_reverse(EnemySlot& e) const {
        e.dir = static_cast<int8_t>(-e.dir);
        e.x_force = 0;
        e.lead_col = e.lead();
    }

    static void enemy_move_x(EnemySlot& e, int8_t speed) {
        const uint8_t raw = static_cast<uint8_t>(speed);
        const uint16_t sum = static_cast<uint16_t>(e.x_force + ((raw & 0x0Fu) << 4));
        int16_t whole = static_cast<int16_t>(raw >> 4);
        if (whole >= 8) {
            whole = static_cast<int16_t>(whole - 16);
        }
        e.x_force = static_cast<uint8_t>(sum);
        int16_t next =
            static_cast<int16_t>(static_cast<int16_t>(e.pos_x) + whole + static_cast<int16_t>(sum >> 8));
        if (next < 0) {
            next = 0;
        }
        e.pos_x = static_cast<uint16_t>(next);
    }

    void enemy_step_ground(EnemySlot& e, uint8_t speed) const {
        enemy_move_x(e, e.dir > 0 ? static_cast<int8_t>(speed) : static_cast<int8_t>(-speed));
        const uint8_t lead = e.lead();
        if (lead != e.lead_col) {
            if (solid(lead, row_of(e.pos_y)) ||
                solid(lead, row_of(static_cast<int16_t>(e.pos_y + kEnemyBoxPx - 1)))) {
                e.pos_x = (e.dir > 0) ? static_cast<uint16_t>((lead << 4) - kEnemyBoxPx)
                                      : static_cast<uint16_t>((lead + 1) << 4);
                enemy_reverse(e);
            } else {
                e.lead_col = lead;
            }
        }
        if (e.grounded == 0) {
            return;
        }
        const uint8_t foot = e.foot();
        if (foot == e.foot_col) {
            return;
        }
        e.foot_col = foot;
        if (floor(foot, row_of(static_cast<int16_t>(e.pos_y + kEnemyBoxPx))) != 0) {
            return;
        }
        if (e.kind == kEnemyKoopaRed && e.state == kEnemyWalk) {
            e.pos_x = (e.dir > 0) ? static_cast<uint16_t>((foot << 4) - kEnemyBoxPx / 2)
                                  : static_cast<uint16_t>(((foot + 1) << 4) - kEnemyBoxPx / 2);
            e.foot_col = e.foot();
            enemy_reverse(e);
            return;
        }
        e.grounded = 0;
        e.dy = 0;
        e.y_accum = 0;
    }

    // enemies.c's step_plant: one counter drives the whole rise, bite, sink and wait
    void step_plant(EnemySlot& e) const {
        const uint16_t base = e.pos_x;
        const int16_t floor_y = static_cast<int16_t>(e.foot_col << 4);

        if (e.timer == 0) {
            const uint16_t left = base > kBlockPx ? static_cast<uint16_t>(base - kBlockPx) : uint16_t{0};

            if (static_cast<uint16_t>(x_pos + kPlayerBoxPx) > left &&
                x_pos < static_cast<uint16_t>(base + 3 * kBlockPx)) {
                return;
            }
        }
        ++e.timer;
        if (e.timer >= kPlantCycleFrames) {
            e.timer = 0;
        }
        if (e.timer < kPlantRisePx) {
            e.pos_y = static_cast<int16_t>(floor_y - static_cast<int16_t>(e.timer));
            e.state = kEnemyPlantUp;
        } else if (e.timer < kPlantRisePx + kPlantHoldFrames) {
            e.pos_y = static_cast<int16_t>(floor_y - kPlantRisePx);
            e.state = kEnemyPlantUp;
        } else if (e.timer < 2 * kPlantRisePx + kPlantHoldFrames) {
            e.pos_y = static_cast<int16_t>(floor_y - (2 * kPlantRisePx + kPlantHoldFrames - e.timer));
            e.state = kEnemyPlantUp;
        } else {
            e.pos_y = floor_y;
            e.state = kEnemyPlantHidden;
        }
    }

    void enemy_step_fall(EnemySlot& e) const {
        const unsigned sum = static_cast<unsigned>(e.y_accum) + kEnemyGravitySubpx;
        e.y_accum = static_cast<uint8_t>(sum);
        if (sum > 0xFFu) {
            e.dy = static_cast<int8_t>(e.dy + 1);
            if (e.dy > kEnemyMaxFallPx) {
                e.dy = kEnemyMaxFallPx;
            }
        }
        e.pos_y = static_cast<int16_t>(e.pos_y + e.dy);
        e.foot_col = e.foot();
        const int16_t row = row_of(static_cast<int16_t>(e.pos_y + kEnemyBoxPx - 1));
        if (!solid(e.foot_col, row)) {
            return;
        }
        e.pos_y = static_cast<int16_t>((row << 4) - kEnemyBoxPx);
        e.dy = 0;
        e.y_accum = 0;
        e.grounded = 1;
    }

    uint8_t enemy_row_load(uint8_t top_row) const {
        uint8_t n = 0;
        for (uint8_t i = 0; i < live; ++i) {
            if (static_cast<uint8_t>(pool[i].pos_y >> 4) == top_row) {
                ++n;
            }
        }
        return n;
    }

    void enemy_spawn() {
        refused = false;
        while (cursor < roster_count) {
            const uint16_t px = static_cast<uint16_t>(roster[cursor].column << 4);
            if (px > static_cast<uint16_t>(cam_x + kScreenWidthPx + kEnemySpawnMarginPx)) {
                return;
            }
            if (static_cast<uint16_t>(px + kEnemyBoxPx + kEnemyDespawnMarginPx) < cam_x) {
                ++cursor;
                continue;
            }
            const uint8_t top_row = static_cast<uint8_t>(roster[cursor].row - 1);
            if (enemy_row_load(top_row) >= kEnemyRowCap) {
                refused = true;
                return;
            }
            if (live >= kEnemySlots) {
                refused = true;
                return;
            }
            EnemySlot* slot = &pool[live];
            ++live;
            *slot = EnemySlot{};
            slot->state = kEnemyWalk;
            slot->kind = roster[cursor].kind;
            slot->pos_x = px;
            slot->pos_y = static_cast<int16_t>(top_row << 4);
            slot->lead_col = slot->lead();
            slot->foot_col = slot->foot();
            if (slot->kind == kEnemyPiranha) {
                slot->state = kEnemyPlantHidden;
                slot->foot_col = roster[cursor].row;
                slot->pos_y = static_cast<int16_t>(slot->foot_col << 4);
            }
            ++cursor;
        }
    }

    void enemy_despawn() {
        uint8_t i = 0;
        while (i < live) {
            const EnemySlot& e = pool[i];
            if (e.pos_y > static_cast<int16_t>(kLevelHeightPx) ||
                static_cast<uint16_t>(e.pos_x + kEnemyBoxPx + kEnemyDespawnMarginPx) < cam_x ||
                e.pos_x > static_cast<uint16_t>(cam_x + kScreenWidthPx + kEnemyDespawnMarginPx)) {
                remove_at(i);
                continue;
            }
            ++i;
        }
    }

    static bool enemies_meet(const EnemySlot& a, const EnemySlot& b) {
        if (a.pos_x + kEnemyBoxPx <= b.pos_x || b.pos_x + kEnemyBoxPx <= a.pos_x) {
            return false;
        }
        return a.pos_y + kEnemyBoxPx > b.pos_y && b.pos_y + kEnemyBoxPx > a.pos_y;
    }

    void enemy_collide() {
        uint8_t i = 0;
        while (static_cast<uint8_t>(i + 1) < live) {
            EnemySlot& a = pool[i];
            bool died = false;
            if (a.state == kEnemySquashed || a.kind == kEnemyPiranha) {
                ++i;
                continue;
            }
            uint8_t j = static_cast<uint8_t>(i + 1);
            while (j < live) {
                EnemySlot& b = pool[j];
                if (b.state == kEnemySquashed || b.kind == kEnemyPiranha || !enemies_meet(a, b)) {
                    ++j;
                    continue;
                }
                if (a.state == kEnemyShellMove && b.state != kEnemyShellMove) {
                    remove_at(j);
                    award(kShellChainTable, kShellChainCount, shell_chain);
                    continue;
                }
                if (b.state == kEnemyShellMove && a.state != kEnemyShellMove) {
                    remove_at(i);
                    award(kShellChainTable, kShellChainCount, shell_chain);
                    died = true;
                    break;
                }
                EnemySlot& left = (a.pos_x <= b.pos_x) ? a : b;
                EnemySlot& right = (&left == &a) ? b : a;
                right.pos_x = static_cast<uint16_t>(left.pos_x + kEnemyBoxPx);
                if (left.dir > 0) {
                    enemy_reverse(left);
                }
                if (right.dir < 0) {
                    enemy_reverse(right);
                }
                ++j;
            }
            if (!died) {
                ++i;
            }
        }
    }

    uint8_t enemy_stomp(EnemySlot& e) {
        if (e.state == kEnemyShellMove) {
            e.state = kEnemyShellIdle;
            e.timer = kShellWakeFrames;
            e.grace = kShellGraceFrames;
            e.x_force = 0;
            shell_chain = 0;
            return kEnemyHitShellStomp;
        }
        award(kStompChainTable, kStompChainCount, stomp_chain);
        if (e.kind == kEnemyKoopa || e.kind == kEnemyKoopaRed) {
            e.state = kEnemyShellIdle;
            e.timer = kShellWakeFrames;
            e.grace = kShellGraceFrames;
            e.x_force = 0;
            return kEnemyHitStomp;
        }
        e.state = kEnemySquashed;
        e.timer = kSquashFrames;
        return kEnemyHitStomp;
    }

    uint8_t enemy_collide_player() {
        const uint16_t left = static_cast<uint16_t>(x_pos + kHitInsetPx);
        const uint16_t right = static_cast<uint16_t>(left + kHitWidthPx);
        const int16_t feet = static_cast<int16_t>(y_pos + foot_h());
        uint8_t hit = kEnemyHitNone;

        for (uint8_t i = 0; i < live; ++i) {
            EnemySlot& e = pool[i];
            if (e.state == kEnemySquashed) {
                continue;
            }
            const uint16_t enemy_left = static_cast<uint16_t>(e.pos_x + kEnemyHitInsetPx);
            if (right <= enemy_left || static_cast<uint16_t>(enemy_left + kEnemyHitWidthPx) <= left) {
                continue;
            }
            if (feet <= e.pos_y || static_cast<int16_t>(e.pos_y + kEnemyBoxPx) <= y_pos) {
                continue;
            }
            if (e.grace != 0) {
                continue;
            }
            const bool from_above = y_speed > 0 && feet <= static_cast<int16_t>(e.pos_y + kEnemyStompLinePx);
            // roster.json: a piranha plant cannot be stomped, only burned or run into
            if (e.kind == kEnemyPiranha) {
                return kEnemyHitDamage;
            }
            if (e.state == kEnemyShellIdle) {
                e.dir = (static_cast<uint16_t>(x_pos + kPlayerBoxPx / 2) <
                         static_cast<uint16_t>(e.pos_x + kEnemyBoxPx / 2))
                            ? int8_t{1}
                            : int8_t{-1};
                e.state = kEnemyShellMove;
                e.grace = kShellGraceFrames;
                e.x_force = 0;
                e.lead_col = e.lead();
                shell_chain = 0;
                if (from_above && hit < kEnemyHitShellStomp) {
                    hit = kEnemyHitShellStomp;
                }
                continue;
            }
            if (from_above) {
                const uint8_t code = enemy_stomp(e);
                if (code > hit) {
                    hit = code;
                }
                continue;
            }
            return kEnemyHitDamage;
        }
        return hit;
    }

    // blocks.c's react(): a question or brick block with something in it pays out once, and the
    // item rises a whole block before it is loose in the world
    void dispense() {
        for (int b = 0; b < lv->block_count && b < 32; ++b) {
            const uint8_t content = lv->blocks[b].content;

            if (lv->blocks[b].column != bumped_column || lv->blocks[b].row != bumped_row) {
                continue;
            }
            if ((spent & (1u << b)) != 0u || content < 2 || content > 4) {
                return; // already opened, or it pays coins and a sprite that only pops
            }
            spent |= 1u << b;
            item_kind = content; // 2 mushroom, 3 star, 4 one-up: the twin only needs them apart
            item_phase = 0;
            item_timer = 0;
            item_dir = 1;
            item_dy = 0;
            item_accum = 0;
            item_grounded = 0;
            item_x = static_cast<uint16_t>(bumped_column << 4);
            item_origin_y = static_cast<int16_t>(bumped_row << 4);
            item_y = item_origin_y;
            return;
        }
    }

    // blocks.c's item_walk and item_fall, the same order and the same constants
    void step_item() {
        if (item_kind == 0) {
            return;
        }
        if (item_phase == 0) {
            ++item_timer;
            item_y = static_cast<int16_t>(item_origin_y - item_timer / kItemRiseFramesPerPx);
            if (item_timer >= kItemRisePx * kItemRiseFramesPerPx) {
                item_phase = 1;
            }
        } else {
            const int16_t next_x = static_cast<int16_t>(item_x + item_dir * kItemWalkPx);
            const int16_t top = row_of(item_y);
            const int16_t bottom = row_of(static_cast<int16_t>(item_y + kPlayerBoxPx - 1));
            const int16_t probe =
                static_cast<int16_t>((item_dir > 0 ? next_x + kPlayerBoxPx - 1 : next_x) >> 4);

            if (solid(probe, top) || solid(probe, bottom)) {
                item_dir = static_cast<int8_t>(-item_dir);
            } else {
                item_x = static_cast<uint16_t>(next_x);
            }
            const int16_t left = static_cast<int16_t>(item_x >> 4);
            const int16_t right = static_cast<int16_t>((item_x + kPlayerBoxPx - 1) >> 4);

            if (item_grounded != 0) {
                const int16_t under = row_of(static_cast<int16_t>(item_y + kPlayerBoxPx));

                if (solid(left, under) || solid(right, under)) {
                    return;
                }
                item_grounded = 0;
            }
            const unsigned sum = static_cast<unsigned>(item_accum) + kItemGravitySubpx;

            item_accum = static_cast<uint8_t>(sum);
            if (sum > 0xFFu) {
                item_dy = static_cast<int8_t>(item_dy + 1);
                if (item_dy > kItemMaxFallPx) {
                    item_dy = kItemMaxFallPx;
                }
            }
            item_y = static_cast<int16_t>(item_y + item_dy);
            if (item_dy >= 0) {
                const int16_t row = row_of(static_cast<int16_t>(item_y + kPlayerBoxPx - 1));

                if (solid(left, row) || solid(right, row)) {
                    item_y = static_cast<int16_t>((row << 4) - kPlayerBoxPx);
                    item_accum = 0;
                    if (item_kind == 3) {
                        item_dy = kStarBouncePx; // the star is the one that keeps hopping
                    } else {
                        item_dy = 0;
                        item_grounded = 1;
                    }
                }
            }
        }
        // he only has to touch it once for the two to be telling different stories from then on
        if (static_cast<uint16_t>(x_pos + kPlayerBoxPx) > item_x &&
            static_cast<uint16_t>(item_x + kPlayerBoxPx) > x_pos && y_pos + foot_h() > item_y &&
            item_y + kPlayerBoxPx > y_pos) {
            collected = true;
            item_kind = 0;
            return;
        }
        if (item_y > kLevelHeightPx ||
            static_cast<int>(item_x) + kPlayerBoxPx + kItemDespawnMarginPx < static_cast<int>(cam_x) ||
            static_cast<int>(item_x) > static_cast<int>(cam_x) + kScreenWidthPx + kItemDespawnMarginPx) {
            item_kind = 0;
        }
    }

    // player.c's player_stomp_bounce: the same launch a jump takes, off the bible's stomp table
    void stomp_bounce(int8_t speed) {
        y_speed = speed;
        y_accum = 0;
        jump_origin_y = y_pos;
        jump_tier = tier_for(abs_speed());
        on_ground = 0;
    }

    // main.c's frame tail: the camera resolves first, then the enemy pass, then mario's reaction
    uint16_t next_spawn_px() const {
        return cursor < roster_count ? static_cast<uint16_t>(roster[cursor].column << 4) : uint16_t{0xFFFF};
    }

    static uint8_t band_for(int16_t feet_y) {
        const int value = feet_y + kCamGroundOffsetPx - kScreenHeightPx;
        return static_cast<uint8_t>(std::max(0, std::min(static_cast<int>(kScyMax), value)));
    }

    void step_world() {
        const uint16_t want = x_pos > kCamFollowX ? static_cast<uint16_t>(x_pos - kCamFollowX) : uint16_t{0};
        cam_x = std::min(want, max_x());
        if (on_ground != 0) {
            band = band_for(static_cast<int16_t>(y_pos + foot_h()));
        }
        if (on_ground == 0 || x_speed != 0) {
            if (cam_y < band) {
                cam_y = static_cast<uint8_t>(std::min<int>(band, cam_y + kCamPanStepPx));
            } else if (cam_y > band) {
                cam_y = static_cast<uint8_t>(std::max<int>(band, cam_y - kCamPanStepPx));
            }
        }
        step_item();
        contact = kEnemyHitNone;
        // enemies.c's idle fast path, mirrored so the two stay frame-identical
        if (live == 0 &&
            static_cast<uint16_t>(cam_x + kScreenWidthPx + kEnemySpawnMarginPx) < next_spawn_px()) {
            check_hazards();
            if (contact == kEnemyHitDamage) {
                damaged = true;
            }
            return;
        }
        // landing ends a stomp chain: the escalation only runs while he stays off the ground
        if (on_ground != 0) {
            stomp_chain = 0;
        }
        enemy_spawn();
        uint8_t i = 0;
        while (i < live) {
            EnemySlot& e = pool[i];
            if (e.grace != 0) {
                --e.grace;
            }
            if (e.kind == kEnemyPiranha) {
                step_plant(e);
                ++i;
                continue;
            }
            if (e.state == kEnemySquashed) {
                if (--e.timer == 0) {
                    remove_at(i);
                    continue;
                }
                ++i;
                continue;
            }
            if (e.state == kEnemyShellIdle) {
                if (--e.timer == 0) {
                    e.state = kEnemyWalk;
                    e.lead_col = e.lead();
                }
                ++i;
                continue;
            }
            if (e.state == kEnemyShellMove) {
                enemy_step_ground(e, static_cast<uint8_t>(kEnemyShellSubpx));
            } else {
                enemy_step_ground(e, static_cast<uint8_t>(kEnemyWalkSubpx));
            }
            if (e.grounded == 0) {
                enemy_step_fall(e);
            }
            ++i;
        }
        if (live > 1) {
            enemy_collide();
        }
        contact = live != 0 ? enemy_collide_player() : uint8_t{kEnemyHitNone};
        enemy_despawn();
        if (contact == kEnemyHitNone) {
            check_hazards();
        }
        if (contact == kEnemyHitDamage) {
            damaged = true;
            return;
        }
        if (contact != kEnemyHitNone) {
            stomp_bounce(contact == kEnemyHitShellStomp ? static_cast<int8_t>(kEnemyShellBouncePx)
                                                        : static_cast<int8_t>(kEnemyStompBouncePx));
        }
    }

    void check_hazards() {
        const uint8_t hazard = hazard_near != 0 ? hazards_contact() : uint8_t{kHazardNone};

        if (hazard == kHazardAxe) {
            axed = true;
            axe_live = 0;
            bowser_live = 0;
        } else if (hazard == kHazardDamage) {
            contact = kEnemyHitDamage;
        }
    }

    bool solid(int column, int row) const {
        if (solid_at(*lv, column, row)) {
            return true;
        }
        const int h = hidden_index(*lv, column, row);
        return h >= 0 && (hidden_solid & (1u << h)) != 0u;
    }

    // terrain_floor_at: a materialized hidden block reads solid, everything else off the table
    uint8_t floor(int column, int row) const {
        const uint8_t f = floor_at(*lv, column, row);

        if (f != 0) {
            return f;
        }
        const int h = hidden_index(*lv, column, row);
        return (h >= 0 && (hidden_solid & (1u << h)) != 0u) ? kFloorSolid : uint8_t{0};
    }

    int foot_h() const {
        return big != 0 ? kPlayerBigBoxPx : kPlayerBoxPx;
    }

    // player_set_big: the feet stay planted and the box grows or shrinks upward
    void set_big(uint8_t next) {
        if (next == big) {
            return;
        }
        y_pos = static_cast<int16_t>(
            y_pos + (next != 0 ? -(kPlayerBigBoxPx - kPlayerBoxPx) : (kPlayerBigBoxPx - kPlayerBoxPx)));
        big = next;
    }

    uint8_t abs_speed() const {
        return static_cast<uint8_t>(x_speed < 0 ? -x_speed : x_speed);
    }

    static int16_t row_of(int16_t py) {
        return py < 0 ? int16_t{-1} : static_cast<int16_t>(py >> 4);
    }

    static int16_t col_of(uint16_t px) {
        return static_cast<int16_t>(px >> 4);
    }

    uint16_t hit_left() const {
        return static_cast<uint16_t>(x_pos + kHitInsetPx);
    }

    uint16_t hit_right() const {
        return static_cast<uint16_t>(x_pos + kHitInsetPx + kHitWidthPx - 1);
    }

    bool fell() const {
        return y_pos >= static_cast<int16_t>(kLevelHeightPx + kPlayerBoxPx);
    }

    bool at_flag() const {
        if (lv->has_flag == 0) {
            return false;
        }
        if (col_of(hit_left()) > static_cast<int16_t>(lv->flag_column) ||
            col_of(hit_right()) < static_cast<int16_t>(lv->flag_column)) {
            return false;
        }
        return row_of(y_pos) <= static_cast<int16_t>(lv->flag_base_row) &&
               row_of(static_cast<int16_t>(y_pos + foot_h() - 1)) >= static_cast<int16_t>(lv->flag_top_row);
    }

    // the run is over the moment the level's own end is reached, whichever end that is
    bool reached_end() const {
        return at_flag() || axed;
    }

    void stop_x() {
        x_speed = 0;
        x_accum = 0;
        x_force = 0;
    }

    void toward_zero(uint8_t delta) {
        if (x_speed > 0) {
            x_speed = static_cast<int8_t>(x_speed - static_cast<int8_t>(delta));
            if (x_speed < 0) {
                x_speed = 0;
            }
        } else if (x_speed < 0) {
            x_speed = static_cast<int8_t>(x_speed + static_cast<int8_t>(delta));
            if (x_speed > 0) {
                x_speed = 0;
            }
        }
    }

    void accelerate(int8_t dir, uint8_t delta, uint8_t max_speed) {
        int16_t next = static_cast<int16_t>(x_speed + dir * static_cast<int16_t>(delta));
        if (next > static_cast<int16_t>(max_speed)) {
            next = static_cast<int16_t>(max_speed);
        }
        if (next < -static_cast<int16_t>(max_speed)) {
            next = static_cast<int16_t>(-static_cast<int16_t>(max_speed));
        }
        x_speed = static_cast<int8_t>(next);
    }

    void step_speed(uint8_t in) {
        const uint8_t run = (in & kInB) != 0 ? 1 : 0;
        const uint8_t speed_abs = abs_speed();
        const int8_t moving_dir = x_speed > 0 ? int8_t{1} : (x_speed < 0 ? int8_t{-1} : int8_t{0});
        const int8_t want_dir =
            (in & kInRight) != 0 ? int8_t{1} : ((in & kInLeft) != 0 ? int8_t{-1} : int8_t{0});
        uint8_t max_speed = kMarioMaxWalkSubpx;
        uint16_t adder = 0;

        const bool skidding = want_dir != 0 && moving_dir != 0 && want_dir != moving_dir;
        if (want_dir == 0 && x_speed == 0) {
            x_accum = 0;
            return;
        }
        if (skidding && speed_abs < kMarioSkidStopSubpx) {
            stop_x();
            return;
        }
        if ((on_ground != 0 && run != 0 && want_dir != 0 && (moving_dir == 0 || moving_dir == want_dir)) ||
            (on_ground == 0 && speed_abs >= kMarioAirRunTierSubpx)) {
            adder = kMarioRunAccel;
        } else if (speed_abs >= kMarioHighSpeedTierSubpx) {
            adder = kMarioHighSpeedAccel;
        } else {
            adder = kMarioWalkAccel;
        }
        if (on_ground != 0) {
            if (run != 0) {
                max_speed = kMarioMaxRunSubpx;
            }
        } else if (speed_abs >= kMarioAirRunTierSubpx) {
            max_speed = kMarioMaxRunSubpx;
        }
        if (skidding) {
            adder = static_cast<uint16_t>(adder * kMarioSkidMultiplier);
        }

        const uint16_t sum = static_cast<uint16_t>(x_accum + adder);
        x_accum = static_cast<uint8_t>(sum);
        const uint8_t delta = static_cast<uint8_t>(sum >> 8);
        if (delta == 0) {
            return;
        }
        if (want_dir == 0 || skidding || speed_abs > max_speed) {
            toward_zero(delta);
        } else {
            accelerate(want_dir, delta, max_speed);
        }
    }

    void move_x() {
        const uint8_t raw = static_cast<uint8_t>(x_speed);
        const uint16_t sum = static_cast<uint16_t>(x_force + ((raw & 0x0Fu) << 4));
        int16_t whole = static_cast<int16_t>(raw >> 4);
        if (whole >= 8) {
            whole = static_cast<int16_t>(whole - 16);
        }
        x_force = static_cast<uint8_t>(sum);
        int16_t next =
            static_cast<int16_t>(static_cast<int16_t>(x_pos) + whole + static_cast<int16_t>(sum >> 8));
        if (next < 0) {
            next = 0;
            stop_x();
        }
        x_pos = static_cast<uint16_t>(next);
    }

    bool blocked_at(int16_t col) const {
        if (solid(col, row_of(y_pos)) || solid(col, row_of(static_cast<int16_t>(y_pos + foot_h() - 1)))) {
            return true;
        }
        return big != 0 && solid(col, row_of(static_cast<int16_t>(y_pos + kPlayerBoxPx)));
    }

    void collide_x() {
        if (x_speed > 0) {
            const int16_t col = col_of(hit_right());
            if (blocked_at(col)) {
                x_pos = static_cast<uint16_t>((col << 4) - kHitInsetPx - kHitWidthPx);
                stop_x();
            }
        } else if (x_speed < 0) {
            const int16_t col = col_of(hit_left());
            if (blocked_at(col)) {
                x_pos = static_cast<uint16_t>(((col + 1) << 4) - kHitInsetPx);
                stop_x();
            }
        }
    }

    uint8_t tier_for(uint8_t speed_abs) const {
        for (uint8_t i = 0; i < kMarioJumpBoundCount; ++i) {
            if (speed_abs <= kJumpTierBounds[i]) {
                return i;
            }
        }
        return static_cast<uint8_t>(kMarioJumpTierCount - 1);
    }

    uint8_t gravity_now(uint8_t a_held) const {
        if (y_speed < 0) {
            if ((a_held != 0 && a_prev != 0) ||
                static_cast<int16_t>(jump_origin_y - y_pos) < kMarioMinRisePx) {
                return kGravityRise[jump_tier];
            }
        }
        return kGravityFall[jump_tier];
    }

    void step_vertical(uint8_t in) {
        const uint8_t a_held = (in & kInA) != 0 ? 1 : 0;
        if (on_ground != 0 && a_held != 0 && a_prev == 0) {
            jump_tier = tier_for(abs_speed());
            y_speed = kJumpSpeed[jump_tier];
            y_accum = 0;
            jump_origin_y = y_pos;
            on_ground = 0;
        }
        const unsigned sum = static_cast<unsigned>(y_accum) + gravity_now(a_held);
        y_accum = static_cast<uint8_t>(sum);
        if (sum > 0xFFu) {
            y_speed = static_cast<int8_t>(y_speed + 1);
            if (y_speed > kMarioMaxFallPx) {
                y_speed = kMarioMaxFallPx;
            }
        }
        y_pos = static_cast<int16_t>(y_pos + y_speed);
    }

    void collide_y() {
        const int16_t left_col = col_of(hit_left());
        const int16_t right_col = col_of(hit_right());
        on_ground = 0;
        if (y_speed < 0) {
            const int16_t row = row_of(y_pos);
            const int hl = hidden_index(*lv, left_col, row);
            const int hr = hidden_index(*lv, right_col, row);
            // player.c's rule: a hidden block joins the collision the instant a rising head reaches it
            const bool left_hit = solid(left_col, row) || hl >= 0;
            const bool right_hit = solid(right_col, row) || hr >= 0;
            if (left_hit || right_hit) {
                const int hit = left_hit ? hl : hr;
                bumped_column = left_hit ? left_col : right_col;
                bumped_row = row;
                if (hit >= 0) {
                    hidden_solid |= (1u << hit);
                }
                dispense();
                y_pos = static_cast<int16_t>((row + 1) << 4);
                y_speed = 0;
                y_accum = 0;
            }
            return;
        }
        const int16_t row = row_of(static_cast<int16_t>(y_pos + foot_h() - 1));
        uint8_t f = floor(left_col, row);
        if ((f & kFloorSolid) == 0 && right_col != left_col) {
            f = static_cast<uint8_t>(f | floor(right_col, row));
        }
        // a thin platform stops only feet that crossed its deck line this frame
        if ((f & kFloorSolid) != 0 ||
            ((f & kFloorThin) != 0 && static_cast<int16_t>(prev_y + foot_h()) <= (row << 4))) {
            y_pos = static_cast<int16_t>((row << 4) - foot_h());
            y_speed = 0;
            y_accum = 0;
            on_ground = 1;
            return;
        }
        if ((y_pos & 15) == 0 && (floor(left_col, static_cast<int16_t>(row + 1)) != 0 ||
                                  floor(right_col, static_cast<int16_t>(row + 1)) != 0)) {
            y_speed = 0;
            y_accum = 0;
            on_ground = 1;
        }
    }

    // player.c's collide_lifts: the same crossed-the-deck-line rule, against the moving decks
    void collide_lifts() {
        const int height = foot_h();
        const int16_t feet = static_cast<int16_t>(y_pos + height);
        const int16_t was = static_cast<int16_t>(prev_y + height);

        riding = 0xFF;
        if (y_speed < 0) {
            return;
        }
        for (uint8_t i = 0; i < lift_count; ++i) {
            const LiftSim& f = lifts[i];

            if (feet < f.y || was > f.y) {
                continue;
            }
            if (static_cast<uint16_t>(x_pos + kHitInsetPx + kHitWidthPx) <= f.x ||
                static_cast<uint16_t>(f.x + kLiftWidthPx) <= static_cast<uint16_t>(x_pos + kHitInsetPx)) {
                continue;
            }
            y_pos = static_cast<int16_t>(f.y - height);
            y_speed = 0;
            y_accum = 0;
            on_ground = 1;
            riding = i;
            return;
        }
    }

    // hazards.c's own frame, run before the player's step exactly as main.c runs it
    void hazards_step() {
        for (uint8_t i = 0; i < lift_count; ++i) {
            LiftSim& f = lifts[i];
            uint16_t pos = f.vertical != 0 ? static_cast<uint16_t>(f.y) : f.x;
            const uint16_t before = pos;

            if (f.dir > 0) {
                pos = static_cast<uint16_t>(pos + kLiftSpeedPx);
                if (pos >= f.hi) {
                    pos = f.hi;
                    f.dir = -1;
                }
            } else {
                pos = static_cast<uint16_t>(pos - kLiftSpeedPx);
                if (pos <= f.lo) {
                    pos = f.lo;
                    f.dir = 1;
                }
            }
            if (f.vertical != 0) {
                f.y = static_cast<int16_t>(pos);
                f.dy = static_cast<int8_t>(static_cast<int16_t>(pos) - static_cast<int16_t>(before));
                f.dx = 0;
            } else {
                f.x = pos;
                f.dx = static_cast<int8_t>(static_cast<int16_t>(pos) - static_cast<int16_t>(before));
                f.dy = 0;
            }
        }
        if (bar_count != 0) {
            const unsigned sum = static_cast<unsigned>(spin_accum) + kFirebarSpinRaw;

            spin_accum = static_cast<uint8_t>(sum);
            if (sum > 0xFFu) {
                spin_step = static_cast<uint8_t>((spin_step + 1) & (kFirebarSteps - 1));
            }
        }
        if (bowser_live != 0) {
            const unsigned sum = static_cast<unsigned>(bowser_force) + 128u;

            bowser_force = static_cast<uint8_t>(sum);
            if (sum > 0xFFu) {
                if (bowser_dir > 0) {
                    ++bowser_x;
                    if (bowser_x >= bowser_hi) {
                        bowser_x = bowser_hi;
                        bowser_dir = -1;
                    }
                } else {
                    --bowser_x;
                    if (bowser_x <= bowser_lo) {
                        bowser_x = bowser_lo;
                        bowser_dir = 1;
                    }
                }
            }
        }
    }

    static bool overlap(uint16_t ax, int16_t ay, int aw, int ah, uint16_t bx, int16_t by, int bw, int bh) {
        if (static_cast<int>(ax) + aw <= static_cast<int>(bx) ||
            static_cast<int>(bx) + bw <= static_cast<int>(ax)) {
            return false;
        }
        return ay + ah > by && by + bh > ay;
    }

    // hazards.c's nearest_bar: the bible spaces 1-4's bars six columns apart so two share the
    // screen, and only the one nearest him is live - the only one drawn and the only one that burns
    uint8_t nearest_bar(uint16_t px) const {
        uint8_t best = 0xFF;
        int closest = 0xFFFF;

        for (uint8_t i = 0; i < bar_count; ++i) {
            const int cx = bar_column[i] * kBlockPx + kBlockPx / 2;
            const int gap = std::abs(cx - static_cast<int>(px));

            if (gap < closest) {
                closest = gap;
                best = i;
            }
        }
        return closest <= kFirebarSegments * kFirebarRadiusPx + kBlockPx ? best : uint8_t{0xFF};
    }

    uint8_t hazards_contact() const {
        const uint16_t left = static_cast<uint16_t>(x_pos + kHitInsetPx);
        const int height = foot_h();

        if (axe_live != 0 && overlap(left, y_pos, kHitWidthPx, height, axe_x, axe_y, kBlockPx, kBlockPx)) {
            return kHazardAxe;
        }
        if (bowser_live != 0 &&
            overlap(left, y_pos, kHitWidthPx, height, bowser_x, bowser_y, kBowserWidthPx, kBowserHeightPx)) {
            return kHazardDamage;
        }
        const uint8_t bar = nearest_bar(static_cast<uint16_t>(left + kHitWidthPx / 2));
        if (bar == 0xFF) {
            return kHazardNone;
        }
        const int cx = bar_column[bar] * kBlockPx + kBlockPx / 2;
        const int cy = bar_row[bar] * kBlockPx + kBlockPx / 2;
        for (int k = 1; k <= kFirebarSegments; ++k) {
            const int fx = cx + kSpinX[spin_step] * k - kFlamePx / 2;
            const int fy = cy + kSpinY[spin_step] * k - kFlamePx / 2;

            if (fx < 0) {
                continue;
            }
            if (overlap(left, y_pos, kHitWidthPx, height, static_cast<uint16_t>(fx), static_cast<int16_t>(fy),
                        kFlamePx, kFlamePx)) {
                return kHazardDamage;
            }
        }
        return kHazardNone;
    }

    void step(uint8_t in) {
        bumped_column = -1;
        bumped_row = -1;
        // main.c's gate, off the camera as it stood at the end of the last frame
        hazard_near = static_cast<uint8_t>(
            hazard_active != 0 &&
                    static_cast<uint16_t>(cam_x + kScreenWidthPx + kHazardMarginPx) > hazard_min_x &&
                    cam_x < static_cast<uint16_t>(hazard_max_x + kHazardMarginPx)
                ? 1
                : 0);
        if (hazard_near != 0) {
            hazards_step();
        }
        // the deck he was on has already moved, so his carry goes on before anything else
        if (riding < lift_count) {
            const int carried = static_cast<int>(x_pos) + lifts[riding].dx;

            x_pos = carried < 0 ? uint16_t{0} : static_cast<uint16_t>(carried);
            y_pos = static_cast<int16_t>(y_pos + lifts[riding].dy);
        }
        step_speed(in);
        move_x();
        collide_x();
        prev_y = y_pos;
        step_vertical(in);
        collide_y();
        if (lift_count != 0) {
            collide_lifts();
        } else {
            riding = 0xFF;
        }
        a_prev = (in & kInA) != 0 ? 1 : 0;
        grounded_for =
            on_ground != 0 ? static_cast<uint8_t>(grounded_for < 255 ? grounded_for + 1 : 255) : uint8_t{0};
        step_world();
    }
};

// the host twin of games/mario/src/camera.c, so the planner can predict mario's screen position
struct CameraSim {
    uint16_t x = 0;
    uint8_t y = 0;
    uint8_t anchor = kCamFollowX;
    uint8_t band = 0;
    uint16_t max_x = kMaxWorldX;

    static uint8_t band_for(int16_t feet_y) {
        int value = feet_y + kCamGroundOffsetPx - kScreenHeightPx;
        value = std::max(0, std::min(static_cast<int>(kScyMax), value));
        return static_cast<uint8_t>(value);
    }

    void step_x(uint16_t mario_x) {
        const uint16_t want = mario_x > anchor ? static_cast<uint16_t>(mario_x - anchor) : uint16_t{0};
        x = std::min(want, max_x);
    }

    void init(const PlayerSim& p) {
        anchor = kCamFollowX;
        band = band_for(static_cast<int16_t>(p.y_pos + p.foot_h()));
        y = band;
        step_x(p.x_pos);
    }

    // select and the d-pad pan are never both driven by the planner, so the replayed script only
    // exercises the follow path here; the dedicated camera tests drive the other two by hand
    void update(const PlayerSim& p) {
        step_x(p.x_pos);
        if (p.on_ground != 0) {
            band = band_for(static_cast<int16_t>(p.y_pos + p.foot_h()));
        }
        const bool standing = p.on_ground != 0 && p.x_speed == 0;
        if (standing) {
            return;
        }
        if (y < band) {
            y = static_cast<uint8_t>(std::min<int>(band, y + kCamPanStepPx));
        } else if (y > band) {
            y = static_cast<uint8_t>(std::max<int>(band, y - kCamPanStepPx));
        }
    }
};

// how far ahead the planner looks before committing to a jump, and the tail of that window it
// measures to tell "still making progress" from "pinned against a wall"
constexpr int kPlanHorizon = 240;
constexpr int kPlanTail = 60;
constexpr int kPlanTailPx = 8;
constexpr int kPlanGainPx = 8;
// only a fall this soon belongs to the decision being made now; a pit two obstacles away shows up
// inside the progress horizon too and must not veto the jump that clears the obstacle in front
constexpr int kPlanFallHorizon = 110;
// how far ahead the walk-and-clear approach watches for something alive, and how long it will
// stand waiting for one to walk on past before it goes looking for a stomp instead
constexpr int kClearWatchPx = 120;
constexpr int kClearWaitFrames = 400;
// and only a death this close is worth a jump that merely postpones it; anything further off is
// the lookahead guessing about a stretch the route has not decided how to run yet
constexpr int kPlanPanicFrames = 70;
// the hold lengths the takeoff search tries, shortest first
constexpr int kPlanHolds[] = {4, 8, 12, 16, 20, 24, 28, 32, 40};

struct Lookahead {
    // the frame the run ended on, in a pit or under a goomba; the planner treats both the same
    int died_at = -1;
    int total = 0;
    int tail = 0;

    bool dies_now() const {
        return died_at >= 0 && died_at < kPlanFallHorizon;
    }
};

// runs the level forward from `sim` holding right (and run), with a held for the first `hold`
// frames, and reports how far it got and whether it ended in the death pit
Lookahead look_ahead(PlayerSim sim, int hold) {
    const int start_x = static_cast<int>(sim.x_pos);
    int mid_x = start_x;
    int end_x = start_x;
    Lookahead out;
    for (int i = 0; i < kPlanHorizon; ++i) {
        uint8_t in = kInRight | kInB;
        if (i < hold) {
            in |= kInA;
        }
        sim.step(in);
        end_x = static_cast<int>(sim.x_pos);
        if (i == kPlanHorizon - kPlanTail) {
            mid_x = end_x;
        }
        if (sim.dead()) {
            out.died_at = i;
            break;
        }
    }
    out.total = end_x - start_x;
    out.tail = end_x - mid_x;
    return out;
}

struct Route {
    std::vector<uint8_t> script;
    PlayerSim end;
    bool reached = false;
};

// the 1-1 planner: hold right and run the whole way, and only spend a jump on a frame where simply
// walking on would fall into a pit or stall against a wall inside the lookahead window. the takeoff
// frame therefore falls out of the search rather than being hand-placed, and the hold length is
// whichever one buys the most ground. `goal` ends the route at a world x; `to_flag` ends it on pole
// contact instead.
Route plan_route(uint16_t goal, bool to_flag, int frame_cap, PlayerSim start = PlayerSim{}) {
    Route route;
    PlayerSim sim = start;
    int jump_left = 0;

    for (int frame = 0; frame < frame_cap; ++frame) {
        uint8_t in = kInRight | kInB;
        if (jump_left > 0) {
            in |= kInA;
            --jump_left;
        } else if (sim.on_ground != 0 && sim.a_prev == 0) {
            const Lookahead plain = look_ahead(sim, 0);
            if (plain.dies_now() || (plain.died_at < 0 && plain.tail < kPlanTailPx)) {
                int best_hold = 0;
                int best_total = plain.dies_now() ? -1 : plain.total;
                for (int hold : kPlanHolds) {
                    const Lookahead tried = look_ahead(sim, hold);
                    if (tried.dies_now() || tried.total <= best_total + kPlanGainPx) {
                        continue;
                    }
                    best_total = tried.total;
                    best_hold = hold;
                }
                if (best_hold > 0) {
                    in |= kInA;
                    jump_left = best_hold - 1;
                }
            }
        }

        route.script.push_back(in);
        sim.step(in);
        if (sim.dead()) {
            break;
        }
        if (to_flag ? sim.at_flag() : (sim.x_pos >= goal && sim.on_ground != 0 && jump_left == 0)) {
            route.reached = true;
            break;
        }
    }
    route.end = sim;
    return route;
}

// --- sub-milestone 8a: the planner for 1-2, 1-3 and 1-4 -----------------------------------------

// the 1-1 planner above holds right and spends a jump wherever walking on would end the run inside
// a 240 frame window. an island level cannot be planned that way: the next pit is always inside the
// window, so nothing ever survives it and the veto has nothing left to compare. the three levels
// after 1-1 are planned around a baseline instead - hold right and run, and hop the moment the
// ground under the feet runs out ahead - and the search only ever swaps that baseline for a move
// that lives out the whole window. two moves join it: a jump that lets go of right at the apex,
// which is how a rider lands on a lift deck and stays on it, and braking to a halt, which is how he
// waits for the deck to come back or a firebar to sweep past. nothing here is hand-placed: the sim
// carries the lifts, bars, plants and the fake bowser, so a wait ends the frame its move starts to work
constexpr int kLevelHorizon = 120;
constexpr int kLevelTail = 40;
// how far past his leading edge the baseline looks for the end of the ground, and how long the hop
// it answers with holds a
constexpr int kEdgeLookPx = 10;
constexpr int kReflexHold = 28;
// bigger than any distance the window can cover, so surviving always beats dying further along
constexpr int kAliveBonus = 4096;
constexpr int kEndBonus = 16384;
// the holds worth trying with right let go at the apex; a lift deck only needs the short ones
constexpr int kRideHolds[] = {4, 8, 12, 16, 20, 24, 28, 32};

// what an option does with the window it is given
constexpr uint8_t kMoveRun = 0;   // the baseline, with a forced hold at the start
constexpr uint8_t kMoveRide = 1;  // jump, let go at the apex, then brake and stay put
constexpr uint8_t kMoveStand = 2; // brake and wait the whole window out

struct Option {
    uint8_t move = kMoveRun;
    int hold = 0;
};

// the baseline's own reflex: the ground under his feet stops within a stride of his leading edge.
// a rider is exempt - the deck he is standing on is not in the grid at all
bool edge_ahead(const PlayerSim& sim) {
    const int ahead = static_cast<int>(sim.hit_right()) + kEdgeLookPx;
    const int row = (sim.y_pos + sim.foot_h()) >> 4;

    return sim.riding == 0xFF && sim.floor(ahead >> 4, row) == 0;
}

struct Probe {
    int died_at = -1;
    int ended_at = -1;
    int total = 0;
    int tail = 0;
    int score = 0;

    bool survives() const {
        return ended_at >= 0 || died_at < 0;
    }
};

// one frame of whatever the option asks for; `left` carries the forced hold and the reflex's own
uint8_t option_input(const PlayerSim& sim, const Option& option, int frame, int& reflex) {
    if (option.move == kMoveStand) {
        return sim.x_speed > 0 ? uint8_t{kInLeft} : uint8_t{0};
    }
    if (option.move == kMoveRide) {
        if (frame < option.hold) {
            return static_cast<uint8_t>(kInRight | kInB | kInA);
        }
        return sim.x_speed > 0 ? uint8_t{kInLeft} : uint8_t{0};
    }
    uint8_t in = static_cast<uint8_t>(kInRight | kInB);
    if (frame < option.hold) {
        return static_cast<uint8_t>(in | kInA);
    }
    if (reflex > 0) {
        --reflex;
        return static_cast<uint8_t>(in | kInA);
    }
    if (sim.on_ground != 0 && sim.a_prev == 0 && sim.grounded_for >= 2 && edge_ahead(sim)) {
        reflex = kReflexHold - 1;
        return static_cast<uint8_t>(in | kInA);
    }
    return in;
}

Probe probe_option(PlayerSim sim, const Option& option) {
    const int start_x = static_cast<int>(sim.x_pos);
    int mid_x = start_x;
    int end_x = start_x;
    int reflex = 0;
    Probe out;

    for (int i = 0; i < kLevelHorizon; ++i) {
        sim.step(option_input(sim, option, i, reflex));
        end_x = static_cast<int>(sim.x_pos);
        if (i == kLevelHorizon - kLevelTail) {
            mid_x = end_x;
        }
        if (sim.reached_end()) {
            out.ended_at = i;
            break;
        }
        if (sim.dead() || sim.collected) {
            out.died_at = i;
            break;
        }
    }
    out.total = end_x - start_x;
    out.tail = end_x - mid_x;
    out.score = out.total + (out.ended_at >= 0 ? kEndBonus : (out.died_at < 0 ? kAliveBonus : 0));
    return out;
}

// the options a grounded decision frame chooses between, the baseline first so a clear stretch
// costs one probe and nothing else. the stand goes last: it survives when nothing else does
std::vector<Option> level_options() {
    std::vector<Option> out;

    out.push_back(Option{kMoveRun, 0});
    for (int hold : kPlanHolds) {
        out.push_back(Option{kMoveRun, hold});
    }
    for (int hold : kRideHolds) {
        out.push_back(Option{kMoveRide, hold});
    }
    out.push_back(Option{kMoveStand, 0});
    return out;
}

// `goal` of 0 runs the level to its own end; anything else stops him standing at that world x
Route plan_level(int level, int frame_cap, uint16_t goal = 0) {
    const std::vector<Option> options = level_options();
    Route route;
    PlayerSim sim;
    Option running;
    int reflex = 0;
    int frame_in = 0;
    int left = 0;

    sim.load_level(level);
    for (int frame = 0; frame < frame_cap; ++frame) {
        // a goal short of the level's own end is a place to stand, so the run brakes into it
        if (goal != 0 && sim.x_pos >= goal) {
            const uint8_t in = sim.x_speed > 0 ? uint8_t{kInLeft} : uint8_t{0};

            route.script.push_back(in);
            sim.step(in);
            if (sim.dead()) {
                break;
            }
            if (sim.x_speed == 0 && sim.on_ground != 0) {
                route.reached = true;
                break;
            }
            continue;
        }
        if (left <= 0 && sim.on_ground != 0 && sim.a_prev == 0 && sim.grounded_for >= 2) {
            const Probe plain = probe_option(sim, options[0]);
            size_t best = 0;

            if (plain.ended_at < 0 && (plain.died_at >= 0 || plain.tail < kPlanTailPx)) {
                int best_score = plain.survives() ? plain.score : -1;

                for (size_t i = 1; i < options.size(); ++i) {
                    const Probe tried = probe_option(sim, options[i]);

                    // only a move that lives out the whole window is worth swapping the run for
                    if (!tried.survives() || tried.score <= best_score + kPlanGainPx) {
                        continue;
                    }
                    best_score = tried.score;
                    best = i;
                }
                if (best == 0 && !plain.survives()) {
                    best = options.size() - 1; // nothing lives: brake and look again next frame
                }
            }
            running = options[best];
            frame_in = 0;
            // a jump is committed for its hold; everything else re-decides on the next frame
            left = std::max(running.hold, 1);
        }

        const uint8_t in = option_input(sim, running, frame_in, reflex);

        ++frame_in;
        --left;
        route.script.push_back(in);
        sim.step(in);
        if (sim.collected) {
            break; // the search should have avoided this; ending here makes the failure loud
        }
        if (goal == 0 && sim.reached_end()) {
            route.reached = true;
            break;
        }
        if (sim.dead()) {
            break;
        }
    }
    route.end = sim;
    return route;
}

// how many pool slots still hold something that can hurt him; a flattened goomba cannot
uint8_t threats(const PlayerSim& sim) {
    uint8_t n = 0;
    for (uint8_t i = 0; i < sim.live; ++i) {
        const uint8_t state = sim.pool[i].state;
        n = static_cast<uint8_t>(n + (state == kEnemyWalk || state == kEnemyShellMove ? 1 : 0));
    }
    return n;
}

// something alive is close enough ahead of him to be worth stopping for
bool threat_ahead(const PlayerSim& sim) {
    for (uint8_t i = 0; i < sim.live; ++i) {
        const EnemySlot& e = sim.pool[i];
        if (e.state != kEnemySquashed && e.pos_x > sim.x_pos && e.pos_x - sim.x_pos < kClearWatchPx) {
            return true;
        }
    }
    return false;
}

// the pan only drifts back to its band while he is moving, so a plan that ends with him standing
// perfectly still can freeze the view wherever it happened to be. a hop in place walks it home
// without moving him, which is what the tests that measure screen rows need
bool append_settle_camera(PlayerSim& sim, std::vector<uint8_t>& script) {
    for (int guard = 0; guard < 6 && sim.cam_y != sim.band; ++guard) {
        for (int i = 0; i < 200; ++i) {
            const uint8_t in = i < 8 ? static_cast<uint8_t>(kInA) : uint8_t{0};

            script.push_back(in);
            sim.step(in);
            if (sim.dead()) {
                return false;
            }
            if (i > 8 && sim.on_ground != 0 && sim.cam_y == sim.band) {
                break;
            }
        }
    }
    return sim.cam_y == sim.band && sim.x_speed == 0 && sim.on_ground != 0;
}

// brings him to a halt and then gets the ground around him empty again. waiting is the cheap way
// out - a goomba that walks past him is forgotten as soon as it clears the camera - and where it
// would reach him first, the wait before a standing jump and its hold are searched instead, so the
// goomba walks into the landing. no frame number below is hand-placed
bool append_stand_clear(PlayerSim& sim, std::vector<uint8_t>& script) {
    // skid to a halt rather than coast: a run coasts most of a hundred px, further than the gap
    for (int i = 0; i < 240 && sim.x_speed > 0; ++i) {
        script.push_back(kInLeft);
        sim.step(kInLeft);
    }
    for (int i = 0; i < 240 && sim.x_speed != 0; ++i) {
        script.push_back(0);
        sim.step(0);
    }
    if (sim.dead() || sim.on_ground == 0) {
        return false;
    }

    for (int round = 0; round < 4; ++round) {
        if (threats(sim) == 0) {
            return true;
        }
        {
            PlayerSim probe = sim;
            std::vector<uint8_t> tail;
            for (int i = 0; i < kClearWaitFrames && threats(probe) != 0 && !probe.dead(); ++i) {
                tail.push_back(0);
                probe.step(0);
            }
            if (!probe.dead() && threats(probe) == 0) {
                sim = probe;
                script.insert(script.end(), tail.begin(), tail.end());
                return true;
            }
        }
        bool got = false;
        for (int wait = 0; wait < kClearWaitFrames && !got; ++wait) {
            for (int hold : kPlanHolds) {
                PlayerSim probe = sim;
                std::vector<uint8_t> tail;
                bool stomped = false;
                bool landed = false;
                for (int i = 0; i < wait + hold + 120 && !landed; ++i) {
                    const uint8_t in =
                        (i >= wait && i < wait + hold) ? static_cast<uint8_t>(kInA) : uint8_t{0};
                    tail.push_back(in);
                    probe.step(in);
                    if (probe.dead()) {
                        break;
                    }
                    stomped = stomped || probe.contact == kEnemyHitStomp;
                    landed = stomped && i > wait && probe.on_ground != 0;
                }
                if (!landed || probe.dead() || probe.x_speed != 0) {
                    continue;
                }
                sim = probe;
                script.insert(script.end(), tail.begin(), tail.end());
                got = true;
                break;
            }
        }
        if (!got) {
            return false;
        }
    }
    if (threats(sim) != 0) {
        return false;
    }
    return append_settle_camera(sim, script);
}

// the approach the camera, pan and block tests lean on. running at 1-1's opening goombas is not
// something the route planner can plan around - they come in pairs a dozen frames apart, no one
// jump clears both, and a jump that does clear one drops him on top of the pyramid instead of the
// ground the tests need him on. so the opening is walked rather than run, stopping to deal with
// each goomba as it comes; anything past the first pipe is handed back to the route planner
Route plan_clear_walk(uint16_t goal, PlayerSim start = PlayerSim{}) {
    const uint16_t opening = static_cast<uint16_t>((first_pipe_column() - 2) * kBlockPx);
    const uint16_t walk_to = std::min(goal, opening);
    Route route;
    PlayerSim sim = start;

    for (int guard = 0; guard < 12; ++guard) {
        // a walk, not a run: a run cannot be braked inside the gap he has to stop in
        for (int i = 0; i < 4000 && sim.x_pos < walk_to && !threat_ahead(sim); ++i) {
            route.script.push_back(kInRight);
            sim.step(kInRight);
        }
        if (sim.dead() || !append_stand_clear(sim, route.script)) {
            return {};
        }
        if (sim.x_pos >= walk_to) {
            break;
        }
    }
    if (sim.x_pos < walk_to || threats(sim) != 0) {
        return {};
    }
    if (sim.x_pos < goal) {
        const Route rest = plan_route(goal, false, 4000, sim);

        if (!rest.reached) {
            return {};
        }
        route.script.insert(route.script.end(), rest.script.begin(), rest.script.end());
        sim = rest.end;
    }
    route.end = sim;
    route.reached = true;
    return route;
}

// walks him out to a world x and brakes to a halt there, jumping over nothing and stomping nothing:
// the enemy tests need whatever is coming for him still walking
Route plan_walk_to(uint16_t goal, PlayerSim start = PlayerSim{}) {
    Route route;
    PlayerSim sim = start;

    for (int i = 0; i < 4000 && sim.x_pos < goal && !sim.dead(); ++i) {
        route.script.push_back(kInRight);
        sim.step(kInRight);
    }
    for (int i = 0; i < 240 && sim.x_speed > 0; ++i) {
        route.script.push_back(kInLeft);
        sim.step(kInLeft);
    }
    for (int i = 0; i < 240 && sim.x_speed != 0; ++i) {
        route.script.push_back(0);
        sim.step(0);
    }
    route.end = sim;
    route.reached = sim.x_pos >= goal && !sim.dead() && sim.on_ground != 0;
    return route;
}

// the world x at which the camera's right edge first reaches a column, which is the frame anything
// standing there spawns; every enemy test waits at one of these rather than running into its target
uint16_t spawn_stand_x(uint16_t column) {
    return static_cast<uint16_t>(column * kBlockPx - kScreenWidthPx + kCamFollowX);
}

PlayerSim lab_sim() {
    PlayerSim sim;
    sim.use_lab();
    return sim;
}

// the lab's roster all stands past 1-1's pits, so the run out to it is the plain route planner's
// job and nothing is in the way until the camera reaches the first of them
Route plan_lab_walk(uint16_t goal) {
    const uint16_t first = spawn_stand_x(kLabEnemies[0].column);
    Route route = plan_route(std::min(goal, first), false, 4000, lab_sim());
    PlayerSim sim = route.end;

    if (!route.reached) {
        return {};
    }
    for (int guard = 0; guard < 16; ++guard) {
        for (int i = 0; i < 4000 && sim.x_pos < goal && !threat_ahead(sim); ++i) {
            route.script.push_back(kInRight);
            sim.step(kInRight);
        }
        // whatever waits past the goal is the caller's business, so it is left walking
        if (sim.x_pos >= goal) {
            break;
        }
        if (sim.dead() || !append_stand_clear(sim, route.script)) {
            return {};
        }
    }
    for (int i = 0; i < 240 && sim.x_speed > 0; ++i) {
        route.script.push_back(kInLeft);
        sim.step(kInLeft);
    }
    for (int i = 0; i < 240 && sim.x_speed != 0; ++i) {
        route.script.push_back(0);
        sim.step(0);
    }
    route.end = sim;
    route.reached = sim.x_pos >= goal && !sim.dead() && sim.on_ground != 0;
    return route;
}

// clears the lab's row of five and then walks on until the koopa behind them is close enough to
// meet him with its goombas already on screen, which is what lets the chain be watched rather than
// happening off the right edge
Route plan_lab_koopa(const LevelEnemy& koopa) {
    const uint16_t meet = static_cast<uint16_t>(koopa.column * kBlockPx - 4 * kBlockPx);
    Route route = plan_lab_walk(static_cast<uint16_t>(spawn_stand_x(koopa.column) - kClearWatchPx));
    PlayerSim sim = route.end;

    if (!route.reached) {
        return {};
    }
    for (int i = 0; i < 400 && sim.x_pos < meet && !sim.dead(); ++i) {
        route.script.push_back(kInRight);
        sim.step(kInRight);
    }
    for (int i = 0; i < 240 && sim.x_speed > 0; ++i) {
        route.script.push_back(kInLeft);
        sim.step(kInLeft);
    }
    for (int i = 0; i < 240 && sim.x_speed != 0; ++i) {
        route.script.push_back(0);
        sim.step(0);
    }
    route.end = sim;
    route.reached = sim.x_pos >= meet && !sim.dead() && sim.on_ground != 0;
    return route;
}

// the slot a shell is sitting or sliding in, or -1
int shell_slot(const PlayerSim& sim) {
    for (uint8_t i = 0; i < sim.live; ++i) {
        if (sim.pool[i].state == kEnemyShellIdle || sim.pool[i].state == kEnemyShellMove) {
            return i;
        }
    }
    return -1;
}

// searches the wait before a standing jump and its hold until the twin reports a stomp; the enemy
// walks into the landing, so no frame here is hand-placed. `frame` is where the stomp lands
struct StompPlan {
    std::vector<uint8_t> script;
    PlayerSim end;
    size_t frame = 0;
    bool found = false;
};

StompPlan plan_stomp(const PlayerSim& start) {
    for (int wait = 0; wait < kClearWaitFrames; ++wait) {
        for (int hold : kPlanHolds) {
            PlayerSim probe = start;
            std::vector<uint8_t> tail;
            size_t at = 0;

            for (int i = 0; i < wait + hold + 120; ++i) {
                const uint8_t in = (i >= wait && i < wait + hold) ? static_cast<uint8_t>(kInA) : uint8_t{0};

                tail.push_back(in);
                probe.step(in);
                if (probe.dead()) {
                    break;
                }
                if (at == 0 && probe.contact == kEnemyHitStomp) {
                    at = tail.size();
                }
                // stopping a few frames past the stomp leaves him still rising off it: whether he
                // then lands on the shell it left or backs away from it is the caller's choice
                if (at != 0 && tail.size() > at + 3) {
                    break;
                }
            }
            if (at == 0 || probe.dead()) {
                continue;
            }
            StompPlan plan;
            plan.script = tail;
            plan.end = probe;
            plan.frame = at;
            plan.found = true;
            return plan;
        }
    }
    return {};
}

// replays a planned script on the rom one frame at a time
void replay(gb::Gameboy& gameboy, const std::vector<uint8_t>& script, size_t from, size_t to) {
    for (size_t i = from; i < to && i < script.size(); ++i) {
        const uint8_t in = script[i];
        gameboy.set_button(gb::Button::Right, (in & kInRight) != 0);
        gameboy.set_button(gb::Button::Left, (in & kInLeft) != 0);
        gameboy.set_button(gb::Button::B, (in & kInB) != 0);
        gameboy.set_button(gb::Button::A, (in & kInA) != 0);
        gameboy.run_frame();
    }
    gameboy.set_button(gb::Button::Right, false);
    gameboy.set_button(gb::Button::Left, false);
    gameboy.set_button(gb::Button::B, false);
    gameboy.set_button(gb::Button::A, false);
}

// the smallest screen y carrying a bg tile in [lo, hi], or -1; the pan tests read the level's own
// rows off the screen this way instead of asking the rom where its camera is
int first_tile_row(const gb::Gameboy& gameboy, uint8_t lo, uint8_t hi) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    for (size_t i = 0; i < ids.size(); ++i) {
        if ((ids[i] & 0x100u) != 0) {
            continue;
        }
        const uint8_t tile = static_cast<uint8_t>(ids[i]);
        if (tile >= lo && tile <= hi) {
            return static_cast<int>(i / gb::kLcdWidth);
        }
    }
    return -1;
}

// --- sub-milestone 5: blocks, items and the pipe sub-area ---------------------------------------

// how many visible 8x8 bg cells carry a tile in [lo, hi]
int bg_family_cells(const gb::Gameboy& gameboy, uint8_t lo, uint8_t hi) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    int n = 0;
    for (uint32_t ty = 0; ty < 18; ++ty) {
        for (uint32_t tx = 0; tx < 20; ++tx) {
            const uint16_t id = ids[(ty * 8 + 3) * gb::kLcdWidth + tx * 8 + 3];
            if ((id & 0x100u) != 0) {
                continue;
            }
            const uint8_t tile = static_cast<uint8_t>(id & 0xFFu);
            if (tile >= lo && tile <= hi) {
                ++n;
            }
        }
    }
    return n;
}

// how many separate enemies a scanline draws, at its busiest row. runs closer together than this
// many transparent px are the same enemy split by mario's own sprite drawing over it, not two
constexpr int kRunGapPx = 8;

int enemy_runs_on_line(const std::span<const uint16_t>& ids, const std::span<const uint8_t>& fb, int y,
                       uint8_t lo, uint8_t hi) {
    int runs = 0;
    int gap = kRunGapPx + 1;
    for (int x = 0; x < static_cast<int>(gb::kLcdWidth); ++x) {
        const size_t i = static_cast<size_t>(y) * gb::kLcdWidth + static_cast<size_t>(x);
        const uint8_t tile = static_cast<uint8_t>(ids[i]);
        const bool lit = (ids[i] & 0x100u) != 0 && tile >= lo && tile <= hi && fb[i] != 0;
        if (!lit) {
            ++gap;
            continue;
        }
        if (gap > kRunGapPx) {
            ++runs;
        }
        gap = 0;
    }
    return runs;
}

// the most enemies any one scanline is asked to draw this frame. the hardware drops the eleventh
// sprite on a line, and a 16x16 enemy costs two, so this is the number the oam cap is about
int busiest_line(const gb::Gameboy& gameboy, uint8_t lo, uint8_t hi) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    const std::span<const uint8_t> fb = gameboy.framebuffer();
    int worst = 0;
    for (int y = 0; y < static_cast<int>(gb::kLcdHeight); ++y) {
        worst = std::max(worst, enemy_runs_on_line(ids, fb, y, lo, hi));
    }
    return worst;
}

int busiest_enemy_line(const gb::Gameboy& gameboy) {
    return busiest_line(gameboy, kTileEnemyLo, kTileEnemyHi);
}

// the sprite box of the sprites drawn from tiles in [lo, hi]; found stays false when none is drawn
struct SpriteBox {
    int left = 0;
    int right = 0;
    int top = 0;
    bool found = false;
};

SpriteBox sprite_box(const gb::Gameboy& gameboy, uint8_t lo, uint8_t hi) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    SpriteBox box;
    for (size_t i = 0; i < ids.size(); ++i) {
        if ((ids[i] & 0x100u) == 0) {
            continue;
        }
        const uint8_t tile = static_cast<uint8_t>(ids[i]);
        if (tile < lo || tile > hi) {
            continue;
        }
        const int x = static_cast<int>(i % gb::kLcdWidth);
        const int y = static_cast<int>(i / gb::kLcdWidth);
        if (!box.found || x < box.left) {
            box.left = x;
        }
        if (!box.found || x > box.right) {
            box.right = x;
        }
        if (!box.found || y < box.top) {
            box.top = y;
        }
        box.found = true;
    }
    return box;
}

// the rgb555 of the first visible pixel belonging to a bg tile in [lo, hi], or -1
int family_color(const gb::Gameboy& gameboy, uint8_t lo, uint8_t hi) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    const std::span<const uint16_t> colors = gameboy.framebuffer_color();
    for (size_t i = 0; i < ids.size(); ++i) {
        if ((ids[i] & 0x100u) != 0) {
            continue;
        }
        const uint8_t tile = static_cast<uint8_t>(ids[i]);
        if (tile >= lo && tile <= hi) {
            return static_cast<int>(colors[i]);
        }
    }
    return -1;
}

// --- sub-milestone 8a: which level type is on screen -------------------------------------------

// color 0 of each palette set's sky, straight out of assets_data.c. no two are close, and the
// backdrop is on screen in every level, so this one probe names the level type the rom loaded
constexpr int kSkyOverworld = 24 | (28 << 5) | (31 << 10);
constexpr int kSkyUnderground = 0 | (0 << 5) | (6 << 10);
constexpr int kSkyCastle = 1 | (1 << 5) | (3 << 10);
constexpr int kSkyTitle = 20 | (24 << 5) | (31 << 10);

int sky_color(const gb::Gameboy& gameboy) {
    return family_color(gameboy, kTileSky, kTileSky);
}

// runs until the backdrop says the named palette set is up, or gives up; returns the frame it took
int wait_for_sky(gb::Gameboy& gameboy, int want, int cap) {
    for (int i = 0; i < cap; ++i) {
        gameboy.run_frame();
        if (sky_color(gameboy) == want) {
            return i;
        }
    }
    return -1;
}

// the first compiled block holding `content`, restricted to a row a jump off the ground can reach
const LevelBlock* block_holding(uint8_t content, uint8_t row) {
    for (uint16_t i = 0; i < kLevel11BlockCount; ++i) {
        if (kLevel11Blocks[i].content == content && kLevel11Blocks[i].row == row) {
            return &kLevel11Blocks[i];
        }
    }
    return nullptr;
}

const LevelBlock* hidden_block() {
    for (uint16_t i = 0; i < kLevel11BlockCount; ++i) {
        if (kLevel11Blocks[i].kind == kBlockListHidden) {
            return &kLevel11Blocks[i];
        }
    }
    return nullptr;
}

// how long a held jump the bump searches use; a full rise clears a block row off the ground with
// room to spare, and the search only cares which cell the head reaches
constexpr int kBumpHoldFrames = 60;

// appends one straight-up jump from wherever the twin stands and reports whether its head bump
// struck (column, row). the script is left mid-jump on success, which is where the rom is watched
bool append_bump(PlayerSim& sim, std::vector<uint8_t>& script, uint16_t column, uint8_t row) {
    for (int i = 0; i < 240 && (sim.on_ground == 0 || sim.a_prev != 0); ++i) {
        script.push_back(0);
        sim.step(0);
        if (sim.dead()) {
            return false;
        }
    }
    if (sim.on_ground == 0) {
        return false;
    }
    for (int i = 0; i < kBumpHoldFrames + 90; ++i) {
        const uint8_t in = i < kBumpHoldFrames ? static_cast<uint8_t>(kInA) : uint8_t{0};
        script.push_back(in);
        sim.step(in);
        // a goomba wandering under him mid-bump would respawn the rom, so that candidate is out
        if (sim.dead()) {
            return false;
        }
        if (sim.bumped_column == static_cast<int16_t>(column) &&
            sim.bumped_row == static_cast<int16_t>(row)) {
            return true;
        }
        if (i > 4 && sim.on_ground != 0) {
            return false;
        }
    }
    return false;
}

struct BumpPlan {
    std::vector<uint8_t> script;
    PlayerSim end;
    bool found = false;
};

// rides the route planner past whatever stands between the level start and the block, then searches
// which frame of that run to let go on: coasting to a stop from any of them puts mario somewhere
// different, and only some of those spots put his head under the cell. the twin reports which cell
// the bump struck, so no frame number here is hand-placed
BumpPlan plan_bump(uint16_t column, uint8_t row, PlayerSim start = PlayerSim{}) {
    const Route approach = plan_clear_walk(static_cast<uint16_t>((column - 3) * kBlockPx), start);
    if (!approach.reached) {
        return {};
    }

    std::vector<uint8_t> full = approach.script;
    std::vector<PlayerSim> states;
    {
        PlayerSim sim = start;
        states.push_back(sim);
        for (uint8_t in : full) {
            sim.step(in);
            states.push_back(sim);
        }
        // the planner stops the moment its goal is met, so walking on covers the columns past it
        for (int i = 0; i < 260 && !sim.dead(); ++i) {
            full.push_back(kInRight);
            sim.step(kInRight);
            states.push_back(sim);
        }
    }

    // coasting from a run overshoots by tens of pixels, and past a pit there is no earlier grounded
    // frame to let go on, so the search also gets to brake into the spot
    static constexpr int kBrakes[] = {0, 4, 8, 12, 16, 20, 26, 32};
    for (size_t f = 0; f < states.size(); ++f) {
        if (states[f].on_ground == 0) {
            continue;
        }
        for (int brake : kBrakes) {
            PlayerSim sim = states[f];
            std::vector<uint8_t> script(full.begin(), full.begin() + static_cast<long>(f));
            for (int i = 0; i < brake; ++i) {
                script.push_back(kInLeft);
                sim.step(kInLeft);
            }
            for (int i = 0; i < 240 && sim.x_speed != 0; ++i) {
                script.push_back(0);
                sim.step(0);
            }
            // the pan freezes the moment he stands perfectly still, so a candidate that comes to
            // rest with the view still drifting is no good to a test measuring screen rows
            if (sim.x_speed != 0 || sim.on_ground == 0 || sim.dead() || sim.cam_y != sim.band) {
                continue;
            }
            if (append_bump(sim, script, column, row)) {
                BumpPlan plan;
                plan.script = script;
                plan.end = sim;
                plan.found = true;
                return plan;
            }
        }
    }
    return {};
}

bool standing_on_pipe(const PlayerSim& sim, uint16_t column, uint8_t top_row) {
    if (sim.on_ground == 0) {
        return false;
    }
    if (PlayerSim::row_of(static_cast<int16_t>(sim.y_pos + kPlayerBoxPx)) != static_cast<int16_t>(top_row)) {
        return false;
    }
    return PlayerSim::col_of(sim.hit_left()) <= static_cast<int16_t>(column + 1) &&
           PlayerSim::col_of(sim.hit_right()) >= static_cast<int16_t>(column);
}

// searches a way to end up standing still on a pipe's cap: the rom only takes a pipe press from
// exactly that stance. every grounded frame of a run to the right is a candidate to brake on, and
// every jump off one is a candidate to land from, so neither the takeoff nor the braking is a
// hand-placed frame number
Route plan_stand_on_pipe(const PlayerSim& start, uint16_t column, uint8_t top_row, int frame_cap) {
    static constexpr int kBrakes[] = {0, 2, 4, 6, 8, 12, 16, 20, 26, 32};
    // a cap is two columns wide and a run cannot be braked inside it, so the walk is searched too
    static constexpr uint8_t kGaits[] = {static_cast<uint8_t>(kInRight | kInB), kInRight};
    PlayerSim base = start;
    std::vector<uint8_t> prefix;

    // brakes to a halt from wherever `sim` is and reports the route when the halt lands on the cap
    const auto settle = [&](const PlayerSim& sim, const std::vector<uint8_t>& tail) -> Route {
        for (int brake : kBrakes) {
            PlayerSim held = sim;
            std::vector<uint8_t> stopping = tail;
            for (int i = 0; i < brake; ++i) {
                stopping.push_back(kInLeft);
                held.step(kInLeft);
            }
            for (int i = 0; i < 240 && held.x_speed != 0; ++i) {
                stopping.push_back(0);
                held.step(0);
            }
            if (held.dead() || held.x_speed != 0 || !standing_on_pipe(held, column, top_row)) {
                continue;
            }
            Route route;
            route.script = prefix;
            route.script.insert(route.script.end(), stopping.begin(), stopping.end());
            route.end = held;
            route.reached = true;
            return route;
        }
        return {};
    };

    for (uint8_t gait : kGaits) {
        base = start;
        prefix.clear();
        for (int frame = 0; frame < frame_cap; ++frame) {
            if (base.on_ground != 0) {
                const Route here = settle(base, {});
                if (here.reached) {
                    return here;
                }
            }
            if (base.on_ground != 0 && base.a_prev == 0) {
                for (int hold : kPlanHolds) {
                    PlayerSim sim = base;
                    std::vector<uint8_t> tail;
                    for (int i = 0; i < 240; ++i) {
                        uint8_t in = gait;
                        if (i < hold) {
                            in |= kInA;
                        }
                        tail.push_back(in);
                        sim.step(in);
                        if (sim.dead()) {
                            break;
                        }
                        if (i > 2 && sim.on_ground != 0) {
                            const Route landed = settle(sim, tail);
                            if (landed.reached) {
                                return landed;
                            }
                            break;
                        }
                    }
                }
                // a run cannot be braked inside two columns, so the other way up is a standing hop
                // with just enough of a rightward nudge to clear the lip
                PlayerSim stopped = base;
                std::vector<uint8_t> lead;
                for (int i = 0; i < 240 && stopped.x_speed != 0; ++i) {
                    lead.push_back(0);
                    stopped.step(0);
                }
                if (stopped.dead() || stopped.x_speed != 0 || stopped.on_ground == 0) {
                    continue;
                }
                for (int hold : kPlanHolds) {
                    for (int nudge = 0; nudge <= 48; nudge += 2) {
                        PlayerSim sim = stopped;
                        std::vector<uint8_t> tail = lead;
                        bool landed = false;
                        for (int i = 0; i < 200 && !landed; ++i) {
                            uint8_t in = 0;
                            if (i < hold) {
                                in |= kInA;
                            }
                            if (i < nudge) {
                                in |= kInRight;
                            }
                            tail.push_back(in);
                            sim.step(in);
                            landed = i > 2 && sim.on_ground != 0;
                        }
                        if (!landed) {
                            continue;
                        }
                        const Route hop = settle(sim, tail);
                        if (hop.reached) {
                            return hop;
                        }
                    }
                }
            }
            prefix.push_back(gait);
            base.step(gait);
            if (base.dead()) {
                break;
            }
        }
    }
    return {};
}

// one frame's worth of what the block and item tests watch for
struct Sighting {
    bool coin_pop = false;
    bool spent_face = false;
    bool item = false;
};

Sighting look(const gb::Gameboy& gameboy) {
    Sighting out;
    out.coin_pop = sprite_box(gameboy, kTileCoinPopLo, kTileCoinPopHi).found;
    out.spent_face = bg_family_cells(gameboy, kTileSpentLo, kTileSpentHi) > 0;
    out.item = sprite_box(gameboy, kTileItemLo, kTileItemHi).found;
    return out;
}

std::vector<Sighting> replay_watched(gb::Gameboy& gameboy, const std::vector<uint8_t>& script) {
    std::vector<Sighting> seen;
    seen.reserve(script.size());
    for (size_t i = 0; i < script.size(); ++i) {
        replay(gameboy, script, i, i + 1);
        seen.push_back(look(gameboy));
    }
    return seen;
}

// the twin state the rom is in once it drops mario into a grid at a start cell
PlayerSim sim_at(uint16_t column, uint8_t surface_row) {
    PlayerSim sim;
    sim.x_pos = static_cast<uint16_t>(column * kBlockPx);
    sim.y_pos = static_cast<int16_t>(surface_row * kBlockPx - kPlayerBoxPx);
    sim.jump_origin_y = sim.y_pos;
    sim.band = PlayerSim::band_for(static_cast<int16_t>(sim.y_pos + sim.foot_h()));
    sim.cam_y = sim.band;
    return sim;
}

// --- sub-milestone 7: powerups ------------------------------------------------------------------

// blocks.c's own rule, mirrored: with the lab armed the compiled hidden block pays a mushroom_fire
// instead of its 1-up, which is the only lone block in 1-1 a dispensed flower can be reached on
const LevelBlock* lab_dispenser() {
    return hidden_block();
}

// the first brick in the compiled list that holds nothing: the cell super mario should break
const LevelBlock* plain_brick() {
    for (uint16_t i = 0; i < kLevel11BlockCount; ++i) {
        if (kLevel11Blocks[i].kind == kBlockListBrick && kLevel11Blocks[i].content == kContentNothing) {
            return &kLevel11Blocks[i];
        }
    }
    return nullptr;
}

// games/mario/src/mario.h's kBumpFrames, the frames a struck block spends drawn one row higher
constexpr int kBumpFramesHost = 8;

// walks the twin toward a world x and lets it coast to a halt there
bool append_walk(PlayerSim& sim, std::vector<uint8_t>& script, uint16_t target) {
    const uint8_t dir = sim.x_pos < target ? static_cast<uint8_t>(kInRight) : static_cast<uint8_t>(kInLeft);

    for (int i = 0; i < 400 && !sim.dead(); ++i) {
        if (dir == kInRight ? sim.x_pos >= target : sim.x_pos <= target) {
            break;
        }
        script.push_back(dir);
        sim.step(dir);
    }
    for (int i = 0; i < 240 && (sim.x_speed != 0 || sim.on_ground == 0); ++i) {
        script.push_back(0);
        sim.step(0);
    }
    return !sim.dead() && sim.on_ground != 0 && sim.x_speed == 0;
}

// walks the twin at a block and searches how long to hold before coasting, so that the standing
// jump appended after it lands its head bump on that exact cell. no frame number here is placed by
// hand: append_bump reports which cell was actually struck
bool append_bump_at(PlayerSim& sim, std::vector<uint8_t>& script, uint16_t column, uint8_t row) {
    const uint16_t target = static_cast<uint16_t>(column * kBlockPx);
    const uint8_t dir = sim.x_pos < target ? static_cast<uint8_t>(kInRight) : static_cast<uint8_t>(kInLeft);

    for (int hold = 0; hold < 400; ++hold) {
        PlayerSim probe = sim;
        std::vector<uint8_t> tail;
        for (int i = 0; i < hold; ++i) {
            tail.push_back(dir);
            probe.step(dir);
        }
        for (int i = 0; i < 300 && (probe.x_speed != 0 || probe.on_ground == 0); ++i) {
            tail.push_back(0);
            probe.step(0);
        }
        if (probe.dead() || probe.on_ground == 0 || probe.x_speed != 0) {
            continue;
        }
        if (append_bump(probe, tail, column, row)) {
            sim = probe;
            script.insert(script.end(), tail.begin(), tail.end());
            return true;
        }
    }
    return false;
}

// blocks.c's boxes_overlap against a resting item: his sprite box is the full 16 wide whatever his
// hitbox does, and the height is whatever body he is carrying
bool touches_item(const PlayerSim& p, uint16_t item_x, int16_t item_y) {
    if (p.x_pos + kPlayerBoxPx <= item_x || item_x + kPlayerBoxPx <= p.x_pos) {
        return false;
    }
    return p.y_pos + p.foot_h() > item_y && item_y + kPlayerBoxPx > p.y_pos;
}

// searches a standing jump (how long a is held, how long a direction is nudged) that brings him
// onto an item resting on top of a block. the item never moves, so no item model is needed
bool append_touch(PlayerSim& sim, std::vector<uint8_t>& script, uint16_t item_x, int16_t item_y) {
    static constexpr uint8_t kDirs[] = {static_cast<uint8_t>(kInRight), static_cast<uint8_t>(kInLeft)};

    for (int hold : kPlanHolds) {
        for (int nudge = 0; nudge <= 60; nudge += 2) {
            for (uint8_t dir : kDirs) {
                PlayerSim probe = sim;
                std::vector<uint8_t> tail;
                for (int i = 0; i < 200; ++i) {
                    uint8_t in = 0;
                    if (i < hold) {
                        in |= kInA;
                    }
                    if (i < nudge) {
                        in |= dir;
                    }
                    tail.push_back(in);
                    probe.step(in);
                    if (probe.dead()) {
                        break;
                    }
                    if (touches_item(probe, item_x, item_y)) {
                        sim = probe;
                        script.insert(script.end(), tail.begin(), tail.end());
                        return true;
                    }
                    if (i > hold && i > nudge && probe.on_ground != 0) {
                        break;
                    }
                }
            }
        }
    }
    return false;
}

// runs the rom with no input until the grow animation starts, which is the first frame his sprite
// is drawn from the super family; -1 when the mushroom never reached him
int wait_for_grow(gb::Gameboy& gameboy, int cap) {
    for (int i = 0; i < cap; ++i) {
        gameboy.run_frame();
        if (mario_at(gameboy).big) {
            return i;
        }
    }
    return -1;
}

// bumps 1-1's opening mushroom block, lets the mushroom walk back into him and rides out the frozen
// grow. the twin comes back untouched: he stands still throughout, and in the lab nothing spawns
// this near the level start, so the frames spent waiting change nothing it models
bool grow_on_the_pyramid(gb::Gameboy& gameboy, PlayerSim& sim) {
    const LevelBlock* block = block_holding(kContentMushroom, 9);
    std::vector<uint8_t> settle;

    REQUIRE(block != nullptr);
    // the caller may hand him over mid-jump, and the planner only searches from a standing start
    for (int i = 0; i < 240 && (sim.on_ground == 0 || sim.a_prev != 0 || sim.x_speed != 0); ++i) {
        settle.push_back(0);
        sim.step(0);
    }
    replay(gameboy, settle, 0, settle.size());
    const BumpPlan plan = plan_bump(block->column, block->row, sim);
    REQUIRE(plan.found);
    replay(gameboy, plan.script, 0, plan.script.size());
    REQUIRE(wait_for_grow(gameboy, 900) >= 0);
    run(gameboy, kGrowFrames + 8);
    // the twin idles the same wait out. the plan leaves him mid-jump, and standing still under no
    // input is a fixed point, so how many frames the mushroom took to walk back does not matter
    sim = plan.end;
    for (int i = 0; i < 400 && (sim.on_ground == 0 || sim.x_speed != 0 || sim.a_prev != 0); ++i) {
        sim.step(0);
    }
    sim.set_big(1);
    return mario_at(gameboy).big && sim.on_ground != 0;
}

// 1 when the level has just restarted: mario back on the bible's start cell with the view at 0
bool at_start_cell(const gb::Gameboy& gameboy) {
    const Mario m = mario_at(gameboy);

    return m.found && !m.big && m.top == kStandTop &&
           m.left == static_cast<int>(LEVEL_1_1_START_COLUMN) * kBlockPx + kMarioArtInset;
}

// how many fireballs are on screen: their lit pixels anywhere, grouped into clusters, one per ball
int fireballs_on_screen(const gb::Gameboy& gameboy) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    const std::span<const uint8_t> fb = gameboy.framebuffer();
    std::set<int> columns;
    for (size_t i = 0; i < ids.size(); ++i) {
        const uint8_t tile = static_cast<uint8_t>(ids[i]);
        if ((ids[i] & 0x100u) == 0 || tile < kTileFireballLo || tile > kTileFireballHi || fb[i] == 0) {
            continue;
        }
        columns.insert(static_cast<int>(i % gb::kLcdWidth));
    }
    int runs = 0;
    int prev = -100;
    for (int x : columns) {
        if (x - prev > 2) {
            ++runs;
        }
        prev = x;
    }
    return runs;
}

int goombas_on_screen(const gb::Gameboy& gameboy) {
    return busiest_line(gameboy, kTileGoombaWalkLo, kTileGoombaSquashHi);
}

// grows him, opens the lab's second dispenser and collects the flower it pays out. the rom comes
// back as fire mario standing beside that lone block, with the twin still in step
bool become_fire(gb::Gameboy& gameboy, PlayerSim& sim) {
    const LevelBlock* dispenser = lab_dispenser();

    REQUIRE(dispenser != nullptr);
    REQUIRE(grow_on_the_pyramid(gameboy, sim));

    const Route out = plan_route(static_cast<uint16_t>((dispenser->column - 6) * kBlockPx), false, 4000, sim);
    REQUIRE(out.reached);
    std::vector<uint8_t> script = out.script;
    sim = out.end;
    REQUIRE(append_bump_at(sim, script, dispenser->column, dispenser->row));
    // physics.json timers.powerup_emergence: the flower needs its whole 64 frame rise first
    for (int i = 0; i < 80; ++i) {
        script.push_back(0);
        sim.step(0);
    }
    REQUIRE(append_walk(sim, script, static_cast<uint16_t>((dispenser->column - 2) * kBlockPx)));
    REQUIRE(append_touch(sim, script, static_cast<uint16_t>(dispenser->column * kBlockPx),
                         static_cast<int16_t>((dispenser->row - 1) * kBlockPx)));
    replay(gameboy, script, 0, script.size());
    run(gameboy, 4);
    for (int i = 0; i < 4; ++i) {
        sim.step(0);
    }
    return mario_wears(gameboy, kColorFireWhite);
}

// the route planner runs, and a running mario jumps clean over the first goomba he meets. so it
// only ever carries him to a stop short of the lab's row, and the last stretch is walked in
int approach_lab_row(gb::Gameboy& gameboy, PlayerSim& sim) {
    const uint16_t stand = spawn_stand_x(kLabEnemies[0].column);
    const Route toward = plan_route(static_cast<uint16_t>(stand - 8 * kBlockPx), false, 4000, sim);

    REQUIRE(toward.reached);
    std::vector<uint8_t> script = toward.script;
    sim = toward.end;
    for (int i = 0; i < 240 && (sim.x_speed != 0 || sim.on_ground == 0 || sim.a_prev != 0); ++i) {
        script.push_back(0);
        sim.step(0);
    }
    REQUIRE(sim.x_pos < stand);
    REQUIRE(append_walk(sim, script, stand));
    replay(gameboy, script, 0, script.size());
    return static_cast<int>(script.size());
}

// every visible cell is one of the families the terrain may legitimately render as
void require_no_garbage(const gb::Gameboy& gameboy) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    for (uint32_t ty = 0; ty < 18; ++ty) {
        for (uint32_t tx = 0; tx < 20; ++tx) {
            const uint16_t id = ids[(ty * 8 + 3) * gb::kLcdWidth + tx * 8 + 3];
            if ((id & 0x100u) != 0) {
                continue;
            }
            REQUIRE(is_known_terrain_family(static_cast<uint8_t>(id & 0xFFu)));
        }
    }
}

